function HL(s, w) { return s.replace(w, '<b class="hl">' + w + '</b>'); }
function P(q, c, w1, w2, i, tr, why) {
  var k = [[0, 1, 2], [1, 0, 2], [2, 0, 1], [1, 2, 0], [0, 2, 1], [2, 1, 0]][i % 6], o = [c, w1, w2];
  return { q: q, o: k.map(function (j) { return o[j]; }), a: k.indexOf(0), tr: tr, why: why };
}
function PL(list) { return list.map(function (x, i) { return P(x[0], x[1], x[2], x[3], i, x[4], x[5]); }); }
function CL(list) { return list.map(function (x) { return { s: x[0], a: x[1], why: x[2] }; }); }

var METIN = "الشَّيْخُ مُحَمَّد مُتَوَلِّي الشَّعْرَاوِيُّ عَالِمُ دِينٍ وَوَزِيرُ أَوْقَافٍ مِصْرِيٌّ سَابِقٌ. يُعَدُّ مِنْ أَشْهَرِ مُفَسِّرِي القُرْآنِ الكَرِيمِ فِي العَصْرِ الحَدِيثِ، فَسَّرَ القُرْآنَ الكَرِيمَ بِطُرُقٍ مُبَسَّطَةٍ، وَلَقَّبَهُ بَعْضُهُمْ بِـ«إِمَامِ الدُّعَاةِ»." +
  "<br>وُلِدَ الشَّعْرَاوِيُّ فِي الخَامِسَ عَشَرَ مِنْ نَيْسَانَ عَامَ ١٩١١م فِي قَرْيَةٍ تَابِعَةٍ لِمُحَافَظَةِ «الدَّقَهْلِيَّةِ» بِمِصْرَ. حَفِظَ القُرْآنَ الكَرِيمَ فِي الحَادِيَةَ عَشْرَةَ مِنْ عُمُرِهِ." +
  "<br>دَرَسَ الشَّعْرَاوِيُّ فِي كُلِّيَّةِ اللُّغَةِ العَرَبِيَّةِ سَنَةَ ١٩٣٧م، وَتَخَرَّجَ فِيهَا عَامَ ١٩٤٠م، وَبَعْدَ تَخَرُّجِهِ عَمِلَ فِي المَعْهَدِ الدِّينِيِّ بِمَدِينَةِ «طَنْطَا»، ثُمَّ انْتَقَلَ بَعْدَ ذَلِكَ إِلَى المَعْهَدِ الدِّينِيِّ بِمَدِينَةِ «الزَّقَازِيقِ» ثُمَّ المَعْهَدِ الدِّينِيِّ بِالإِسْكَنْدَرِيَّةِ." +
  "<br>بَعْدَ خِبْرَةٍ طَوِيلَةٍ انْتَقَلَ الشَّيْخُ الشَّعْرَاوِيُّ إِلَى العَمَلِ فِي السُّعُودِيَّةِ عَامَ ١٩٥٠م، فَعَمِلَ أُسْتَاذًا فِي كُلِّيَّةِ الشَّرِيعَةِ بِجَامِعَةِ أُمِّ القُرَى. وَفِي عَامِ ١٩٦٣م رَجَعَ الشَّيْخُ الشَّعْرَاوِيُّ إِلَى مِصْرَ، ثُمَّ سَافَرَ بَعْدَ ذَلِكَ إِلَى الجَزَائِرِ لِلتَّدْرِيسِ، وَقَضَى فِيهَا حَوَالَيْ سَبْعِ سَنَوَاتٍ." +
  "<br>لِلشَّيْخِ الشَّعْرَاوِيِّ عَدَدٌ مِنَ المُؤَلَّفَاتِ، وَأَشْهَرُ هَذِهِ المُؤَلَّفَاتِ «تَفْسِيرُ الشَّعْرَاوِيِّ لِلْقُرْآنِ الكَرِيمِ»، وَ«الإِسْرَاءُ وَالمِعْرَاجُ»، وَ«الإِنْسَانُ الكَامِلُ: مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ»." +
  "<br>تُوُفِّيَ الشَّيْخُ مُحَمَّد مُتَوَلِّي الشَّعْرَاوِيُّ رَحِمَهُ اللهُ فِي ١٧ مِنْ حُزَيْرَانَ عَامَ ١٩٩٨م.";
var METIN_TR = "Şeyh Muhammed Mütevellî eş-Şa‘râvî, Mısırlı bir din âlimi ve eski Vakıflar bakanıdır. Modern çağda Kur’ân-ı Kerîm’in en meşhur müfessirlerinden sayılır; Kur’ân’ı sade yollarla tefsir etmiştir. Bazıları ona “dâvetçilerin imamı” lakabını vermiştir." +
  "<br>Şa‘râvî 15 Nisan 1911’de Mısır’da Dekahliye vilayetine bağlı bir köyde doğdu. Kur’ân-ı Kerîm’i on bir yaşında ezberledi." +
  "<br>1937’de Arap Dili Fakültesinde okudu ve 1940’ta oradan mezun oldu. Mezuniyetinden sonra Tanta şehrindeki dinî enstitüde çalıştı; ardından Zagazig’deki, sonra da İskenderiye’deki dinî enstitüye geçti." +
  "<br>Uzun bir tecrübeden sonra 1950’de Suudi Arabistan’da çalışmaya gitti ve Ümmü’l-Kurâ Üniversitesi Şeriat Fakültesinde hoca olarak çalıştı. 1963’te Mısır’a döndü; sonra ders vermek için Cezayir’e gitti ve orada yaklaşık yedi yıl kaldı." +
  "<br>Şeyh Şa‘râvî’nin birçok eseri vardır; en meşhurları “Şa‘râvî Tefsiri”, “İsrâ ve Mi‘râc” ve “Kâmil İnsan: Hz. Muhammed (s.a.v.)”dir." +
  "<br>Şeyh Muhammed Mütevellî eş-Şa‘râvî (Allah ona rahmet etsin) 17 Haziran 1998’de vefat etti.";
var SOZLUK = [["عَالِمُ دِينٍ", "din âlimi"], ["وَزِيرُ أَوْقَافٍ", "Vakıflar (Diyanet) bakanı"], ["سَابِقٌ", "eski, önceki"], ["يُعَدُّ", "sayılır"], ["مُفَسِّرُو القُرْآنِ", "Kur’an müfessirleri"], ["العَصْرُ الحَدِيثُ", "modern çağ"], ["بِطُرُقٍ مُبَسَّطَةٍ", "sade, kolay yollarla"], ["لَقَّبَهُ", "ona lakap verdi"], ["إِمَامُ الدُّعَاةِ", "dâvetçilerin imamı"], ["نَيْسَانُ", "nisan"], ["تَابِعَةٌ لِـ", "…e bağlı"], ["مُحَافَظَةٌ", "il, vilayet"], ["مِنْ عُمُرِهِ", "yaşında"], ["تَخَرَّجَ فِي / مِنْ", "…den mezun oldu"], ["المَعْهَدُ الدِّينِيُّ", "dinî enstitü"], ["انْتَقَلَ إِلَى", "…e geçti, taşındı"], ["خِبْرَةٌ", "tecrübe"], ["أُسْتَاذٌ", "hoca, profesör"], ["كُلِّيَّةُ الشَّرِيعَةِ", "Şeriat (İlahiyat) Fakültesi"], ["لِلتَّدْرِيسِ", "ders vermek için"], ["حَوَالَيْ", "yaklaşık"], ["المُؤَلَّفَاتُ", "eserler"], ["تُوُفِّيَ", "vefat etti"], ["حُزَيْرَانُ", "haziran"]];

